#!/usr/bin/env python3
"""prep.py E TAG: orbit conflict graph of LINES under the cyclic group generated by h = (g133)^E.
E=19 gives order 7 orbits, E=7 gives order 19 orbits. Two orbits are adjacent if some line of one meets some line
of the other. Orbits with two concurrent lines inside themselves can never be chosen and are dropped.
Writes graph_TAG.bin (int64 nv, int64 M2; int64 off[nv+1]; int32 adj[M2]; adjacency sorted),
members_TAG.bin (int32 s, int32 nv, then nv*s line ids), start_TAG.txt (vertex ids of the orbits of RL.txt)."""
import sys, numpy as np
SH = '/home/user/degree-diameter/research/squads/c157b-r1/shared/'
C3 = '/home/user/degree-diameter/research/squads/c157b-r1/c3/'
E, TAG = int(sys.argv[1]), sys.argv[2]
b = open(SH + 'hex_q11.bin', 'rb').read()
q, N, L = (int(x) for x in np.frombuffer(b[:12], dtype=np.int32)); Q1 = q + 1
LP = np.frombuffer(b[12:12 + 4 * L * Q1], dtype=np.int32).reshape(L, Q1).astype(np.int64)
flat_p = LP.reshape(-1); flat_l = np.repeat(np.arange(L), Q1)
PL = flat_l[np.lexsort((flat_l, flat_p))].reshape(N, Q1).astype(np.int32)   # lines through each point
p = np.loadtxt(SH + 'g133_lines.txt', dtype=np.int64)
assert len(p) == L and len(np.unique(p)) == L
h = np.arange(L)
for _ in range(E): h = p[h]
orb = np.full(L, -1, dtype=np.int64); k = 0
for i in range(L):
    if orb[i] >= 0: continue
    j = i
    while orb[j] < 0:
        orb[j] = k; j = h[j]
    k += 1
sizes = np.bincount(orb); s = int(sizes[0]); assert (sizes == s).all()
print('E', E, 'orbits', k, 'orbit size', s, flush=True)
mem = np.argsort(orb, kind='stable').reshape(k, s)
orb32 = orb.astype(np.int32)
bad = np.zeros(k, bool); A_list = []; B_list = []
for i in range(Q1):
    a = orb32[PL[:, i]]
    for j in range(i + 1, Q1):
        bb = orb32[PL[:, j]]
        eq = a == bb
        if eq.any(): bad[a[eq]] = True
        m = ~eq
        A_list.append(a[m]); B_list.append(bb[m])
A = np.concatenate(A_list).astype(np.int64); B = np.concatenate(B_list).astype(np.int64)
del A_list, B_list
valid = ~bad; vi = np.nonzero(valid)[0]; nv = len(vi)
newid = -np.ones(k, np.int64); newid[vi] = np.arange(nv)
print('valid orbits', nv, 'of', k, flush=True)
keep = valid[A] & valid[B]
A = newid[A[keep]]; B = newid[B[keep]]
lo = np.minimum(A, B); hi = np.maximum(A, B)
key = np.unique(lo * nv + hi)
lo = key // nv; hi = key % nv
M = len(key)
src = np.concatenate([lo, hi]); dst = np.concatenate([hi, lo])
o = np.argsort(src * nv + dst, kind='stable'); src = src[o]; dst = dst[o].astype(np.int32)
deg = np.bincount(src, minlength=nv)
off = np.zeros(nv + 1, np.int64); off[1:] = np.cumsum(deg)
print('undirected edges', M, 'avg deg %.1f min %d max %d' % (deg.mean(), deg.min(), deg.max()), flush=True)
with open(C3 + 'graph_%s.bin' % TAG, 'wb') as f:
    np.array([nv, len(dst)], dtype=np.int64).tofile(f)
    off.tofile(f); dst.tofile(f)
with open(C3 + 'members_%s.bin' % TAG, 'wb') as f:
    np.array([s, nv], dtype=np.int32).tofile(f)
    mem[vi].astype(np.int32).tofile(f)
# start set: orbits of RL
RL = np.loadtxt(SH + 'RL.txt', dtype=np.int64).reshape(-1)
cnt = np.bincount(orb[RL], minlength=k)
full = np.nonzero(cnt)[0]
assert (cnt[full] == s).all(), 'RL is not a union of orbits'
start = newid[full]
assert (start >= 0).all(), 'RL contains an internally invalid orbit'
mask = np.zeros(nv, bool); mask[start] = True
conf_in = int((mask[src] & mask[dst]).sum()) // 2
print('RL orbits', len(start), 'lines', len(start) * s, 'conflicts inside RL', conf_in, flush=True)
np.savetxt(C3 + 'start_%s.txt' % TAG, np.sort(start), fmt='%d')
# free vertices outside RL (no neighbour in RL)
conf_rl = np.bincount(src[mask[dst]], minlength=nv)
free = np.nonzero((~mask) & (conf_rl == 0))[0]
print('vertices outside RL with no RL neighbour (free):', len(free), 'min conf outside RL', conf_rl[~mask].min(),
      'mean conf outside RL %.1f' % conf_rl[~mask].mean(), flush=True)
